def analyze_matrix(ticker: str) -> pd.DataFrame:
    row = next((r for r in SCANNER_ROWS if r["Ticker"] == ticker), None)
    sector = TICKER_FACTS.get(ticker, {}).get("Sector", "Unknown")
    if row:
        trend = row["Trend"]
        bias = row["Bias"]
        liquidity = row["Liquidity"]
        premium_quality = "Good" if row["Premium"] >= 1 else "Average"
        d = row["Delta"]
        weekly_macd = "Bullish" if trend == "Bullish" else "Neutral"
        daily_macd = "Bullish" if row["Score"] >= 80 else "Neutral"
        hourly_rsi = "Constructive" if bias == "Bullish" else "Neutral"
        five_min = "Pass" if row["Strategy"] in ("Covered Call", "Cash-Secured Put") else "Neutral"
        bb = "Support zone" if bias == "Bullish" else "Middle band"
        confluence = f"{row['Confluence']} / 10"
    else:
        seed = sum(ord(c) for c in ticker)
        liquidity = "Good" if seed % 2 else "Average"
        premium_quality = "Good" if seed % 3 else "Average"
        weekly_macd = "Bullish" if seed % 4 else "Neutral"
        daily_macd = "Bullish" if seed % 5 else "Neutral"
        hourly_rsi = "Constructive" if seed % 2 else "Mixed"
        five_min = "Neutral"
        bb = "Middle band"
        confluence = f"{5 + seed % 4} / 10"
        trend = "Bullish" if seed % 3 else "Neutral"
    return pd.DataFrame([
        ["Weekly MACD", weekly_macd, "Big picture trend filter"],
        ["Daily MACD", daily_macd, "Current momentum posture"],
        ["Hourly RSI / trend", hourly_rsi, "Swing rhythm and exhaustion check"],
        ["5-minute confirmation", five_min, "Most important for CC & CSP entry timing"],
        ["Bollinger position", bb, "Where price sits within the range"],
        ["Liquidity", liquidity, "Can you realistically get in and out?"],
        ["Premium quality", premium_quality, "Does the option premium justify the risk?"],
        ["Confluence", confluence, "How many things line up together?"],
        ["Sector", sector, "Context, not a trigger by itself"],
        ["Trend posture", trend, "Directional read"],
    ], columns=["Factor", "Status", "Commentary"])

def color_word(word: str) -> str:
    s = word.lower()
    if s == "bullish":
        return "<span class='mc-colored-bullish'>Bullish</span>"
    if s == "neutral":
        return "<span class='mc-colored-neutral'>Neutral</span>"
    if s == "bearish":
        return "<span class='mc-colored-bearish'>Bearish</span>"
    return f"<span class='mc-colored-blue'>{word}</span>"

def radar_response(prompt: str, active_ticker: str, focus: str) -> str:
    p = prompt.lower().strip()
    if not p:
        return "RADAR is ready. Ask about the scanner, a ticker, or how to use one of the strategy sections."
    if "assignment" in p:
        return f"Assignment risk matters most when the short strike is at a level you would not want to own. {active_ticker.upper()} should only be a short-put candidate if you genuinely want shares there."
    if "stronger" in p or "improve" in p:
        return "A stronger candidate usually needs cleaner support, enough premium for the risk, no event landmine, and confirmation that matches the strategy. CC & CSP especially wants clean short-term confirmation, not just a nice weekly chart."
    if "which strategy" in p or "best" in p:
        scores = scorecard_for_ticker(active_ticker)
        best_name = recommendation(scores)
        return f"For {active_ticker.upper()}, the best current fit in this prototype is {best_name}. If that does not match your plan, check whether the timeframe, premium quality, and assignment comfort agree with your intent."
    if "plain english" in p or "explain" in p:
        return f"In plain English: {active_ticker.upper()} looks best for {focus} if the chart, premium, and comfort level all agree. The score is not the trade. The score is only a fast filter."
    return "RADAR reads this platform as scanner first, scorecard second, and education right beside it. Use Scanner to surface names, Analyze to test a ticker, Learn to understand the why, and DELTA to map the payoff."

# ── Google Gemini API key helper ─────────────────────────────────────────
_GEMINI_KEY_FALLBACK = ""  # Set key in Streamlit Secrets: GOOGLE_API_KEY

def get_gemini_api_key() -> str | None:
    if _GEMINI_KEY_FALLBACK:
        return _GEMINI_KEY_FALLBACK
    for name in ("GOOGLE_API_KEY", "GEMINI_API_KEY"):
        try:
            val = st.secrets.get(name)
            if val:
                return val
        except Exception:
            pass
        val = os.environ.get(name)
        if val:
            return val
    return None

def live_radar_response(prompt: str, ticker: str, focus: str, scope: str) -> str:
    """Call Google Gemini API via urllib — no SDK needed."""
    api_key = get_gemini_api_key()
    if not api_key:
        return "RADAR is not connected yet. Add your Google API key to Streamlit Secrets to enable live responses."

    system_msg = (
        "You are RADAR — Research, Analysis, Decision, and Reasoning — the AI assistant "
        "inside Market Compass, a platform built by Practical Income Investing (PII). "
        "You specialize in income-focused options trading: covered calls, cash-secured puts, "
        "credit spreads, LEAPS, and buy-writes. You know PII's 7 Fundamental Principles: "
        "Growth, Moat, Management, Margins, Cash Flow, Risk, and Timing. "
        "You are concise, practical, and plain-spoken. No fluff. No markdown formatting. "
        "If asked about a specific ticker, give actionable commentary. "
        "If a question is outside trading/investing, politely redirect. "
        f"Current focus: {focus}. Scope: {scope}. Active ticker context: {ticker.upper() if ticker else 'None'}."
    )

    payload = json.dumps({
        "system_instruction": {"parts": [{"text": system_msg}]},
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {"maxOutputTokens": 400, "temperature": 0.4},
    }).encode("utf-8")

    url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={api_key}"
    req = Request(url, data=payload, headers={"content-type": "application/json"}, method="POST")
    try:
        with urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            return data["candidates"][0]["content"]["parts"][0]["text"].strip()
    except HTTPError as e:
        body = e.read().decode("utf-8") if hasattr(e, "read") else ""
        return f"RADAR API error ({e.code}). Please try again. {body[:120]}"
    except Exception as e:
        return f"RADAR could not connect. Please try again. ({e})"

def breakeven(strategy: str, stock_price: float, strike: float, premium: float) -> float | None:
    if strategy == "Cash-Secured Put":
        return strike - premium
    if strategy == "Covered Call":
        return stock_price - premium
    if strategy == "Put Credit Spread":
        return strike - premium
    if strategy == "Call Debit Spread":
        return strike + premium
    return None

def payoff_curve(strategy: str, stock_price: float, strike: float, premium: float, width: float, contracts: int, lower_pct: float, upper_pct: float) -> pd.DataFrame:
    prices = [stock_price * (lower_pct + i * (upper_pct - lower_pct) / 40) for i in range(41)]
    mult = 100 * contracts
    pnl = []
    for p in prices:
        if strategy == "Cash-Secured Put":
            val = premium - max(strike - p, 0)
        elif strategy == "Covered Call":
            val = (p - stock_price) + premium - max(p - strike, 0)
        elif strategy == "Put Credit Spread":
            short_strike = strike
            long_strike = strike - width
            val = premium - max(short_strike - p, 0) + max(long_strike - p, 0)
        else:
            long_strike = strike
            short_strike = strike + width
            debit = premium
            val = max(p - long_strike, 0) - max(p - short_strike, 0) - debit
        pnl.append(val * mult)
    return pd.DataFrame({"Price": prices, "PnL": pnl})

def max_profit_loss(strategy: str, stock_price: float, strike: float, premium: float, width: float, contracts: int) -> Tuple[float | str, float | str]:
    mult = 100 * contracts
    if strategy == "Cash-Secured Put":
        return premium * mult, (strike - premium) * mult
    if strategy == "Covered Call":
        max_profit = ((strike - stock_price) + premium) * mult
        max_loss = (stock_price - premium) * mult
        return max_profit, max_loss
    if strategy == "Put Credit Spread":
        max_profit = premium * mult
        max_loss = (width - premium) * mult
        return max_profit, max_loss
    max_profit = (width - premium) * mult
    max_loss = premium * mult
    return max_profit, max_loss

def guide_text(strategy: str) -> List[str]:
    guides = {
        "Cash-Secured Put": [
            "Best when you like the stock and would own it if assigned.",
            "Strike choice should respect support and assignment comfort.",
            "Premium alone is not a reason to sell the put."
        ],
        "Covered Call": [
            "Best when you already want stock exposure and income now.",
            "You are choosing to cap upside above the strike.",
            "Respect ex-dividend timing and assignment odds."
        ],
        "Put Credit Spread": [
            "Best when you want defined risk on a bullish thesis.",
            "Width matters because it controls max loss.",
            "Do not ignore liquidity just because risk is capped."
        ],
        "Call Debit Spread": [
            "Best when bullish but looking for a lower-capital directional trade.",
            "Defined risk helps, but timing still matters.",
            "Know your target and exit before entry."
        ],
    }
    return guides[strategy]

def playbook_text(name: str) -> str:
    data = PLAYBOOKS[name]
    lines = [f"# {data['title']}", "", data["summary"], "", "## Key points"]
    lines.extend([f"- {b}" for b in data["bullets"]])
    return "\n".join(lines)


ALPHA_VANTAGE_BASE_URL = "https://www.alphavantage.co/query"


def _get_streamlit_secret(name: str) -> str | None:
    try:
        if name in st.secrets:
            value = st.secrets[name]
            if value:
                return str(value).strip()
    except Exception:
        pass
    return None


def get_alpha_vantage_api_key() -> str | None:
    if _AV_KEY_FALLBACK:
        return _AV_KEY_FALLBACK
    for name in ("ALPHAVANTAGE_API_KEY", "ALPHA_VANTAGE_API_KEY"):
        secret_value = _get_streamlit_secret(name)
        if secret_value:
            return secret_value
        env_value = os.getenv(name, "").strip()
        if env_value:
            return env_value
    return None


def alpha_vantage_configured() -> bool:
    return bool(get_alpha_vantage_api_key())


def _alpha_vantage_request(function: str, **params) -> Dict:
    api_key = get_alpha_vantage_api_key()
    if not api_key:
        return {"_error": "missing_api_key"}

    query = {"function": function, "apikey": api_key, **params}
    url = f"{ALPHA_VANTAGE_BASE_URL}?{urlencode(query)}"
    request = Request(url, headers={"User-Agent": "MarketCompass/23"})

    try:
        with urlopen(request, timeout=12) as response:
            payload = response.read().decode("utf-8")
        data = json.loads(payload)
    except HTTPError as exc:
        return {"_error": f"HTTP error {exc.code}"}
    except URLError as exc:
        return {"_error": f"Network error: {exc.reason}"}
    except Exception as exc:
        return {"_error": f"Request failed: {exc}"}

    if not isinstance(data, dict):
        return {"_error": "Unexpected Alpha Vantage response."}

    for key in ("Error Message", "Information", "Note"):
        if data.get(key):
            return {"_error": str(data.get(key))}

    return data


@st.cache_data(ttl=240, show_spinner=False)
def fetch_alpha_vantage_quote(symbol: str) -> Dict:
    return _alpha_vantage_request("GLOBAL_QUOTE", symbol=symbol.upper().strip())


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_alpha_vantage_overview(symbol: str) -> Dict:
    return _alpha_vantage_request("OVERVIEW", symbol=symbol.upper().strip())


@st.cache_data(ttl=300, show_spinner=False)
def fetch_alpha_vantage_intraday(symbol: str, interval: str = "5min") -> Dict:
    return _alpha_vantage_request(
        "TIME_SERIES_INTRADAY",
        symbol=symbol.upper().strip(),
        interval=interval,
        adjusted="true",
        extended_hours="false",
        outputsize="compact",
    )


@st.cache_data(ttl=300, show_spinner=False)
def fetch_alpha_vantage_market_status() -> Dict:
    return _alpha_vantage_request("MARKET_STATUS")


def _safe_float(value) -> float | None:
    try:
        if value in (None, "", "None"):
            return None
        return float(str(value).replace(",", ""))
    except Exception:
        return None


def _safe_int(value) -> int | None:
    try:
        if value in (None, "", "None"):
            return None
        return int(float(str(value).replace(",", "")))
    except Exception:
        return None


def _normalize_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value).lower())


def _find_mapping_value(mapping: Dict, *fragments: str):
    normalized_fragments = [_normalize_key(fragment) for fragment in fragments]
    for key, value in mapping.items():
        normalized_key = _normalize_key(key)
        if any(fragment and fragment in normalized_key for fragment in normalized_fragments):
            return value
    return None


def parse_alpha_vantage_quote(data: Dict) -> Dict | None:
    if not isinstance(data, dict) or data.get("_error"):
        return None

    quote = data.get("Global Quote", data)
    if not isinstance(quote, dict) or not quote:
        return None

    return {
        "symbol": _find_mapping_value(quote, "symbol") or "",
        "price": _safe_float(_find_mapping_value(quote, "price")),
        "change": _safe_float(_find_mapping_value(quote, "change")),
        "change_percent": str(_find_mapping_value(quote, "changepercent") or "").replace("%", "").strip(),
        "volume": _safe_int(_find_mapping_value(quote, "volume")),
        "previous_close": _safe_float(_find_mapping_value(quote, "previousclose")),
        "latest_trading_day": _find_mapping_value(quote, "latesttradingday") or "",
    }


def parse_alpha_vantage_overview(data: Dict) -> Dict | None:
    if not isinstance(data, dict) or data.get("_error"):
        return None

    name = data.get("Name") or data.get("Symbol") or ""
    sector = data.get("Sector") or "—"
    industry = data.get("Industry") or "—"
    market_cap = _safe_float(data.get("MarketCapitalization"))
    pe_ratio = _safe_float(data.get("PERatio"))
    eps = _safe_float(data.get("EPS"))
    analyst_target = _safe_float(data.get("AnalystTargetPrice"))
    beta = _safe_float(data.get("Beta"))
    profit_margin = _safe_float(data.get("ProfitMargin"))
    week_high = _safe_float(data.get("52WeekHigh"))
    week_low = _safe_float(data.get("52WeekLow"))

    if not name and all(
        value is None or value == "—"
        for value in [market_cap, pe_ratio, eps, analyst_target, beta, profit_margin, week_high, week_low]
    ):
        return None

    dividend_yield = _safe_float(data.get("DividendYield"))
    if dividend_yield is not None and dividend_yield <= 1:
        dividend_yield *= 100

    return {
        "name": name,
        "sector": sector,
        "industry": industry,
        "market_cap": market_cap,
        "pe_ratio": pe_ratio,
        "eps": eps,
        "analyst_target": analyst_target,
        "beta": beta,
        "profit_margin": profit_margin,
        "dividend_yield": dividend_yield,
        "week_high": week_high,
        "week_low": week_low,
    }


def alpha_vantage_error_text(data: Dict | None) -> str | None:
    if isinstance(data, dict) and data.get("_error"):
        return str(data.get("_error"))
    return None


def parse_alpha_vantage_intraday(data: Dict) -> pd.DataFrame:
    if not isinstance(data, dict) or data.get("_error"):
        return pd.DataFrame()

    series_key = next((key for key in data if str(key).lower().startswith("time series")), None)
    series = data.get(series_key) if series_key else None
    if not isinstance(series, dict) or not series:
        return pd.DataFrame()

    rows = []
    for timestamp, values in series.items():
        if not isinstance(values, dict):
            continue
        rows.append({
            "timestamp": pd.to_datetime(timestamp),
            "open": _safe_float(_find_mapping_value(values, "open")),
            "high": _safe_float(_find_mapping_value(values, "high")),
            "low": _safe_float(_find_mapping_value(values, "low")),
            "close": _safe_float(_find_mapping_value(values, "close")),
            "volume": _safe_float(_find_mapping_value(values, "volume")),
        })

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).dropna(subset=["timestamp", "close"]).sort_values("timestamp").reset_index(drop=True)


def summarize_alpha_vantage_market_status(data: Dict) -> str | None:
    if not isinstance(data, dict) or data.get("_error"):
        return None

    entries = []
    for value in data.values():
        if isinstance(value, list):
            entries.extend(item for item in value if isinstance(item, dict))

    def get_item_field(item: Dict, *fragments: str):
        return _find_mapping_value(item, *fragments)

    if not entries:
        return None

    preferred = None
    for item in entries:
        text_blob = " ".join(str(v) for v in item.values()).lower()
        if "united states" in text_blob and "equity" in text_blob:
            preferred = item
            break
    if preferred is None:
        preferred = entries[0]

    venue = get_item_field(preferred, "marketname", "exchange", "region", "market") or "Market"
    status = get_item_field(preferred, "currentstatus", "status", "marketstatus") or "Status unavailable"
    return f"{venue}: {status}"


def format_compact_currency(value: float | None) -> str:
    if value is None:
        return "—"
    if abs(value) >= 1_000_000_000_000:
        return f"${value / 1_000_000_000_000:,.2f}T"
    if abs(value) >= 1_000_000_000:
        return f"${value / 1_000_000_000:,.2f}B"
    if abs(value) >= 1_000_000:
        return f"${value / 1_000_000:,.2f}M"
    return f"${value:,.2f}"


def format_price(value: float | None) -> str:
    return "—" if value is None else f"${value:,.2f}"


def format_percent_value(value: float | None, decimals: int = 2) -> str:
    return "—" if value is None else f"{value:.{decimals}f}%"


def format_signed_change(change: float | None, change_percent: str | None) -> str:
    if change is None and not change_percent:
        return "—"
    pieces = []
    if change is not None:
        pieces.append(f"{change:+.2f}")
    if change_percent:
        pieces.append(f"({change_percent}%)")
    return " ".join(pieces)


def format_week_range(low: float | None, high: float | None) -> str:
    if low is None or high is None:
        return "—"
    return f"${low:,.2f} to ${high:,.2f}"


def build_intraday_chart(symbol: str, df: pd.DataFrame) -> go.Figure:
    chart_df = df.tail(60) if len(df) > 60 else df
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=chart_df["timestamp"], y=chart_df["close"], mode="lines", name=symbol, line=dict(width=2)))
    fig.update_layout(
        height=280,
        margin=dict(l=10, r=10, t=10, b=10),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(255,255,255,0.03)",
        showlegend=False,
        xaxis=dict(title="", gridcolor="rgba(255,255,255,0.08)", zeroline=False),
        yaxis=dict(title="", gridcolor="rgba(255,255,255,0.08)", zeroline=False, tickprefix="$"),
        font=dict(color="#eef6ff"),
    )
    return fig


def render_alpha_vantage_setup_help() -> None:
    st.info("Alpha Vantage is wired in, but the API key is not loaded yet. Add it through Streamlit secrets or an environment variable, then rerun the app.")
    st.code('ALPHAVANTAGE_API_KEY = "your_key_here"', language='toml')
    st.caption("You can also use the environment variable name ALPHA_VANTAGE_API_KEY if that fits your setup better.")



