def get_radar_logo_bytes() -> bytes | None:
    """Return Ask RADAR logo bytes from a local file if present, otherwise use the embedded logo."""
    candidate_paths = []
    try:
        base_dir = Path(__file__).resolve().parent
        candidate_paths.extend([
            base_dir / 'ask_radar_logo_v30.png',
            base_dir / 'ask_radar_logo_transparentish.png',
            base_dir / 'a_digital_logo_design_displays_the_words_ask_rada.png',
        ])
    except NameError:
        pass
    candidate_paths.extend([
        Path('/mnt/data/ask_radar_logo_v30.png'),
        Path('/mnt/data/ask_radar_logo_transparentish.png'),
        Path('/mnt/data/a_digital_logo_design_displays_the_words_ask_rada.png'),
    ])
    for path in candidate_paths:
        if path.exists():
            try:
                return path.read_bytes()
            except Exception:
                pass
    embedded_logo_b64 = ""
    try:
        return base64.b64decode(embedded_logo_b64)
    except Exception:
        return None


