@dataclass
class Leg:
    asset_type: str
    kind: str
    side: str
    strike: float
    entry_price: float
    qty: int
    delta: float


@dataclass
class Structure:
    strategy: str
    bias: str
    summary: str
    tags: str
    guide: str
    accent: str
    legs: List[Leg]
    net_debit: float
    net_credit: float
    max_profit: float
    max_loss: float
    breakeven: float
    capital_required: float
    chance_of_profit: float
    note: str


def normal_cdf(x: float) -> float:
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))




def html_block(html: str) -> str:
    cleaned = textwrap.dedent(html).strip()
    return "\n".join(line.lstrip() for line in cleaned.splitlines())


def render_html(html: str) -> None:
    st.markdown(html_block(html), unsafe_allow_html=True)

def get_live_price_for_ticker(ticker: str) -> float | None:
    clean = ticker.strip().upper()
    if not clean or not alpha_vantage_configured():
        return None
    quote = parse_alpha_vantage_quote(fetch_alpha_vantage_quote(clean))
    if quote and quote.get("price") is not None:
        return float(quote["price"])
    return None


def get_price_for_ticker(ticker: str) -> float:
    clean = ticker.strip().upper()
    live_price = get_live_price_for_ticker(clean)
    if live_price is not None:
        return round(live_price, 2)
    if clean in MOCK_PRICES:
        return MOCK_PRICES[clean]
    seed = sum(ord(ch) for ch in clean) if clean else 0
    base = 75 + (seed % 175)
    return round(float(base) + 0.37, 2)


def strike_increment(price: float) -> float:
    if price < 25:
        return 0.5
    if price < 200:
        return 1.0
    if price < 1000:
        return 5.0
    return 25.0


def option_price_estimate(kind: str, stock_price: float, strike: float, dte: int, iv: float) -> float:
    remaining_days = max(dte, 0)
    intrinsic = 0.0
    if kind == "call":
        intrinsic = max(stock_price - strike, 0.0)
    if kind == "put":
        intrinsic = max(strike - stock_price, 0.0)

    time_fraction = max(remaining_days, 1) / 365.0
    distance = abs(stock_price - strike) / max(stock_price, 1.0)
    extrinsic_base = stock_price * iv * math.sqrt(time_fraction) * 0.14
    moneyness_factor = clamp(1.25 - (distance * 5.0), 0.12, 1.25)

    if remaining_days == 0:
        return round(max(intrinsic, 0.0), 2)

    price = intrinsic + (extrinsic_base * moneyness_factor)
    return round(max(price, 0.05), 2)


def option_delta_estimate(kind: str, stock_price: float, strike: float, dte: int, iv: float) -> float:
    sigma = max(0.06, iv * math.sqrt(max(dte, 1) / 365.0))
    scaled = (stock_price - strike) / max(stock_price * sigma * 1.2, 0.001)
    call_delta = 1.0 / (1.0 + math.exp(-scaled))
    call_delta = clamp(call_delta, 0.05, 0.95)
    if kind == "call":
        return round(call_delta, 2)
    return round(call_delta - 1.0, 2)


def format_money(value: float) -> str:
    if math.isinf(value):
        return "Unlimited"
    return f"${value:,.2f}"


def format_percent(value: float) -> str:
    return f"{value:.1f}%"


def probability_above(level: float, stock_price: float, dte: int, iv: float) -> float:
    sigma = max(stock_price * iv * math.sqrt(max(dte, 1) / 365.0), stock_price * 0.01)
    z_score = (level - stock_price) / sigma
    return clamp((1.0 - normal_cdf(z_score)) * 100.0, 0.5, 99.5)


def probability_below(level: float, stock_price: float, dte: int, iv: float) -> float:
    sigma = max(stock_price * iv * math.sqrt(max(dte, 1) / 365.0), stock_price * 0.01)
    z_score = (level - stock_price) / sigma
    return clamp(normal_cdf(z_score) * 100.0, 0.5, 99.5)


def build_structure(strategy: str, stock_price: float, strike: float, width: float, dte: int, iv: float, contracts: int) -> Structure:
    meta = STRATEGIES[strategy]
    accent = meta["accent"]
    bias = meta["bias"]
    summary = meta["summary"]
    tags = meta["tags"]
    guide = meta["guide"]
    legs: List[Leg] = []

    net_debit = 0.0
    net_credit = 0.0
    max_profit = 0.0
    max_loss = 0.0
    breakeven = stock_price
    capital_required = 0.0
    chance_of_profit = 50.0
    note = summary

    if strategy == "Long Call":
        premium = option_price_estimate("call", stock_price, strike, dte, iv)
        delta = option_delta_estimate("call", stock_price, strike, dte, iv)
        legs.append(Leg("option", "call", "long", strike, premium, contracts, delta))
        net_debit = premium * 100.0 * contracts
        max_profit = math.inf
        max_loss = net_debit
        breakeven = strike + premium
        capital_required = net_debit
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)

    if strategy == "Long Put":
        premium = option_price_estimate("put", stock_price, strike, dte, iv)
        delta = option_delta_estimate("put", stock_price, strike, dte, iv)
        legs.append(Leg("option", "put", "long", strike, premium, contracts, delta))
        net_debit = premium * 100.0 * contracts
        max_profit = max((strike - premium) * 100.0 * contracts, 0.0)
        max_loss = net_debit
        breakeven = strike - premium
        capital_required = net_debit
        chance_of_profit = probability_below(breakeven, stock_price, dte, iv)

    if strategy == "Bull Call Spread":
        long_premium = option_price_estimate("call", stock_price, strike, dte, iv)
        short_strike = strike + width
        short_premium = option_price_estimate("call", stock_price, short_strike, dte, iv)
        legs.append(Leg("option", "call", "long", strike, long_premium, contracts, option_delta_estimate("call", stock_price, strike, dte, iv)))
        legs.append(Leg("option", "call", "short", short_strike, short_premium, contracts, option_delta_estimate("call", stock_price, short_strike, dte, iv)))
        net_debit = (long_premium - short_premium) * 100.0 * contracts
        max_profit = max((width - (long_premium - short_premium)) * 100.0 * contracts, 0.0)
        max_loss = max(net_debit, 0.0)
        breakeven = strike + max((long_premium - short_premium), 0.0)
        capital_required = max(net_debit, 0.0)
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)

    if strategy == "Bull Put Spread":
        long_strike = max(strike - width, 0.01)
        short_premium = option_price_estimate("put", stock_price, strike, dte, iv)
        long_premium = option_price_estimate("put", stock_price, long_strike, dte, iv)
        legs.append(Leg("option", "put", "short", strike, short_premium, contracts, option_delta_estimate("put", stock_price, strike, dte, iv)))
        legs.append(Leg("option", "put", "long", long_strike, long_premium, contracts, option_delta_estimate("put", stock_price, long_strike, dte, iv)))
        credit = short_premium - long_premium
        net_credit = credit * 100.0 * contracts
        max_profit = max(net_credit, 0.0)
        max_loss = max((width - credit) * 100.0 * contracts, 0.0)
        breakeven = strike - max(credit, 0.0)
        capital_required = max_loss
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)

    if strategy == "Covered Call":
        call_premium = option_price_estimate("call", stock_price, strike, dte, iv)
        call_delta = option_delta_estimate("call", stock_price, strike, dte, iv)
        legs.append(Leg("stock", "stock", "long", stock_price, stock_price, contracts, 1.0))
        legs.append(Leg("option", "call", "short", strike, call_premium, contracts, call_delta))
        net_debit = ((stock_price * 100.0) - (call_premium * 100.0)) * contracts
        max_profit = max(((strike - stock_price) + call_premium) * 100.0 * contracts, 0.0)
        max_loss = max((stock_price - call_premium) * 100.0 * contracts, 0.0)
        breakeven = stock_price - call_premium
        capital_required = net_debit
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)
        note = "Buy-write planning shell. Upside caps at the short call strike while premium lowers stock cost basis."

    if strategy == "Cash-Secured Put":
        premium = option_price_estimate("put", stock_price, strike, dte, iv)
        delta = option_delta_estimate("put", stock_price, strike, dte, iv)
        legs.append(Leg("option", "put", "short", strike, premium, contracts, delta))
        net_credit = premium * 100.0 * contracts
        max_profit = net_credit
        max_loss = max((strike - premium) * 100.0 * contracts, 0.0)
        breakeven = strike - premium
        capital_required = max((strike * 100.0 * contracts) - net_credit, 0.0)
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)

    if strategy == "Short Put":
        premium = option_price_estimate("put", stock_price, strike, dte, iv)
        delta = option_delta_estimate("put", stock_price, strike, dte, iv)
        legs.append(Leg("option", "put", "short", strike, premium, contracts, delta))
        net_credit = premium * 100.0 * contracts
        max_profit = net_credit
        max_loss = max((strike - premium) * 100.0 * contracts, 0.0)
        breakeven = strike - premium
        capital_required = max((strike * 100.0 * contracts) - net_credit, 0.0)
        chance_of_profit = probability_above(breakeven, stock_price, dte, iv)
        note = "Short put planning shell. Capital is modeled conservatively here; later versions can plug in margin-specific logic."

    if strategy == "Bear Call Spread":
        long_strike = strike + width
        short_premium = option_price_estimate("call", stock_price, strike, dte, iv)
        long_premium = option_price_estimate("call", stock_price, long_strike, dte, iv)
        legs.append(Leg("option", "call", "short", strike, short_premium, contracts, option_delta_estimate("call", stock_price, strike, dte, iv)))
        legs.append(Leg("option", "call", "long", long_strike, long_premium, contracts, option_delta_estimate("call", stock_price, long_strike, dte, iv)))
        credit = short_premium - long_premium
        net_credit = credit * 100.0 * contracts
        max_profit = max(net_credit, 0.0)
        max_loss = max((width - credit) * 100.0 * contracts, 0.0)
        breakeven = strike + max(credit, 0.0)
        capital_required = max_loss
        chance_of_profit = probability_below(breakeven, stock_price, dte, iv)

    return Structure(
        strategy=strategy,
        bias=bias,
        summary=summary,
        tags=tags,
        guide=guide,
        accent=accent,
        legs=legs,
        net_debit=max(net_debit, 0.0),
        net_credit=max(net_credit, 0.0),
        max_profit=max_profit,
        max_loss=max(max_loss, 0.0),
        breakeven=round(breakeven, 2),
        capital_required=max(capital_required, 0.0),
        chance_of_profit=chance_of_profit,
        note=note,
    )


def future_leg_value(leg: Leg, stock_price: float, remaining_days: int, iv: float) -> float:
    if leg.asset_type == "stock":
        return stock_price
    return option_price_estimate(leg.kind, stock_price, leg.strike, remaining_days, iv)


def structure_value(structure: Structure, stock_price: float, remaining_days: int, iv: float) -> Tuple[float, float]:
    pnl = 0.0
    mark_value = 0.0
    for leg in structure.legs:
        quantity = leg.qty
        if leg.asset_type == "stock":
            future_value = future_leg_value(leg, stock_price, remaining_days, iv)
            leg_pnl = (future_value - leg.entry_price) * 100.0 * quantity
            mark = future_value * 100.0 * quantity
            if leg.side == "short":
                leg_pnl *= -1.0
                mark *= -1.0
            pnl += leg_pnl
            mark_value += mark
        else:
            future_value = future_leg_value(leg, stock_price, remaining_days, iv)
            mark = future_value * 100.0 * quantity
            if leg.side == "long":
                leg_pnl = (future_value - leg.entry_price) * 100.0 * quantity
                pnl += leg_pnl
                mark_value += mark
            if leg.side == "short":
                leg_pnl = (leg.entry_price - future_value) * 100.0 * quantity
                pnl += leg_pnl
                mark_value -= mark
    return pnl, mark_value


def build_price_grid(stock_price: float, range_percent: float, step_percent: float) -> List[float]:
    low = stock_price * (1.0 - range_percent / 100.0)
    high = stock_price * (1.0 + range_percent / 100.0)
    prices = []
    current = low
    step_value = stock_price * (step_percent / 100.0)
    if step_value <= 0:
        step_value = max(stock_price * 0.005, 0.1)
    while current <= high + (step_value / 2.0):
        prices.append(round(current, 2))
        current += step_value
    if round(high, 2) not in prices:
        prices.append(round(high, 2))
    return prices


def day_schedule(dte: int) -> List[int]:
    if dte <= 7:
        return list(range(0, dte + 1))
    if dte <= 14:
        return list(range(0, dte + 1))
    if dte <= 30:
        days = [0, 1, 2, 3, 4, 5, 7, 10, 14, 18, 22, 26, dte]
        return sorted(list(dict.fromkeys(day for day in days if day <= dte)))
    days = [0, 1, 2, 3, 5, 7, 10, 14]
    extra = np.linspace(21, dte, 8)
    for value in extra:
        days.append(int(round(float(value))))
    days.append(dte)
    days = sorted(list(dict.fromkeys(day for day in days if day <= dte)))
    return days


def time_label(day_from_now: int, dte: int) -> str:
    if day_from_now == 0:
        return "Today"
    if day_from_now == dte:
        return "EXP"
    return f"Day {day_from_now}"


def metric_value(pnl: float, mark_value: float, structure: Structure, mode: str) -> float:
    risk_base = max(structure.max_loss, structure.capital_required, 1.0)
    if mode == "Profit / Loss $":
        return pnl
    if mode == "Profit / Loss %":
        return (pnl / max(structure.capital_required, 1.0)) * 100.0
    if mode == "Contract Value":
        return mark_value
    return (pnl / risk_base) * 100.0


def build_table_df(structure: Structure, stock_price: float, dte: int, iv: float, table_range: float, table_step: float, mode: str) -> pd.DataFrame:
    prices = build_price_grid(stock_price, table_range, table_step)
    days = day_schedule(dte)
    rows = []
    for scenario_price in prices:
        row = {
            "Underlying": scenario_price,
            "Move": ((scenario_price / stock_price) - 1.0) * 100.0,
        }
        for day in days:
            remaining_days = max(dte - day, 0)
            pnl, mark_value = structure_value(structure, scenario_price, remaining_days, iv)
            row[time_label(day, dte)] = metric_value(pnl, mark_value, structure, mode)
        rows.append(row)
    df = pd.DataFrame(rows)
    return df.sort_values(by='Underlying', ascending=False, ignore_index=True)


def style_metric_value(value: float, max_abs: float, mode: str) -> str:
    if max_abs <= 0:
        return "background-color: rgba(18, 35, 64, 0.75); color: #f3f8ff;"
    intensity = min(abs(value) / max_abs, 1.0)
    alpha = 0.16 + (0.36 * intensity)
    if value > 0:
        return f"background-color: rgba(0, 200, 120, {alpha:.3f}); color: #f4fff8;"
    if value < 0:
        return f"background-color: rgba(255, 80, 120, {alpha:.3f}); color: #fff6f8;"
    return "background-color: rgba(18, 35, 64, 0.75); color: #f3f8ff;"


def render_styled_table(df: pd.DataFrame, mode: str) -> str:
    df = df.rename(columns={'Underlying': 'Price'})
    metric_cols = [col for col in df.columns if col not in {"Price", "Move"}]
    max_abs = 0.0
    if metric_cols:
        max_abs = float(np.nanmax(np.abs(df[metric_cols].to_numpy(dtype=float))))

    def style_df(cell_value: float) -> str:
        return style_metric_value(float(cell_value), max_abs, mode)

    formatters = {
        "Price": lambda value: f"${value:,.2f}",
        "Move": lambda value: f"{value:+.2f}%",
    }
    for column in metric_cols:
        if mode in {"Profit / Loss %", "Risk Progress %"}:
            formatters[column] = lambda value: f"{value:,.1f}%"
        else:
            formatters[column] = lambda value: f"${value:,.0f}"

    styler = df.style.hide(axis="index")
    if metric_cols:
        styler = styler.map(style_df, subset=pd.IndexSlice[:, metric_cols])
    styler = styler.set_table_styles(
        [
            {"selector": "table", "props": [("width", "100%"), ("border-collapse", "collapse"), ("font-size", "9px"), ("table-layout", "auto")]},
            {"selector": "th", "props": [("background", "#eff3f9"), ("color", "#5d6f8f"), ("padding", "5px 4px"), ("border", "1px solid #d3dbe8"), ("white-space", "nowrap"), ("text-align", "center")]},
            {"selector": "td", "props": [("padding", "3px 4px"), ("border", "1px solid rgba(220, 230, 245, 0.12)"), ("text-align", "center"), ("white-space", "nowrap")]},
            {"selector": "tbody tr:hover td", "props": [("filter", "brightness(1.06)")]},
        ]
    )
    styler = styler.format(formatters)
    return "<div class='delta-table-wrap'>" + styler.to_html() + "</div>"


