def probability_curve(stock_price: float, dte: int, iv: float, price_grid: List[float]) -> List[float]:
    sigma = max(stock_price * iv * math.sqrt(max(dte, 1) / 365.0), stock_price * 0.01)
    coeff = 1.0 / (sigma * math.sqrt(2.0 * math.pi))
    values = []
    for price in price_grid:
        exponent = -((price - stock_price) ** 2) / (2.0 * sigma**2)
        values.append(coeff * math.exp(exponent))
    max_value = max(values) if values else 1.0
    return [value / max_value * 45.0 for value in values]


def plot_payoff_chart(structure: Structure, ticker: str, stock_price: float, dte: int, iv: float, chart_range: float, mode: str, graph_day: int) -> go.Figure:
    x_prices = np.linspace(stock_price * (1.0 - chart_range / 100.0), stock_price * (1.0 + chart_range / 100.0), 161)
    remaining_days = max(dte - graph_day, 0)
    metric_values = []
    hover_moves = []
    for scenario_price in x_prices:
        pnl, mark_value = structure_value(structure, float(scenario_price), remaining_days, iv)
        metric_values.append(metric_value(pnl, mark_value, structure, mode))
        move_pct = ((float(scenario_price) / stock_price) - 1.0) * 100.0
        hover_moves.append(f"{move_pct:+.2f}%")

    y_values = np.array(metric_values)
    pos_y = np.where(y_values >= 0, y_values, np.nan)
    neg_y = np.where(y_values < 0, y_values, np.nan)
    prob = probability_curve(stock_price, remaining_days if remaining_days > 0 else 1, iv, list(x_prices))
    ticker_label = ticker.strip().upper() or "Ticker"

    figure = go.Figure()
    figure.add_trace(
        go.Scatter(
            x=x_prices,
            y=prob,
            mode="lines",
            line={"color": "rgba(74, 184, 255, 0.55)", "width": 2},
            fill="tozeroy",
            fillcolor="rgba(74, 184, 255, 0.10)",
            name="Probability",
            yaxis="y2",
            hovertemplate="Price: %{x:$,.2f}<br>Probability shape: %{y:.1f}<extra></extra>",
        )
    )
    figure.add_trace(
        go.Scatter(
            x=x_prices,
            y=neg_y,
            mode="lines",
            line={"color": "#ff4d6d", "width": 3},
            fill="tozeroy",
            fillcolor="rgba(255, 77, 109, 0.18)",
            name="Loss Zone",
            customdata=np.column_stack([hover_moves]),
            hovertemplate=f"{ticker_label} Price: %{{x:$,.2f}}<br>Move: %{{customdata[0]}}<br>Value: %{{y:,.2f}}<extra></extra>",
        )
    )
    figure.add_trace(
        go.Scatter(
            x=x_prices,
            y=pos_y,
            mode="lines",
            line={"color": "#00e676", "width": 3},
            fill="tozeroy",
            fillcolor="rgba(0, 230, 118, 0.16)",
            name="Profit Zone",
            customdata=np.column_stack([hover_moves]),
            hovertemplate=f"{ticker_label} Price: %{{x:$,.2f}}<br>Move: %{{customdata[0]}}<br>Value: %{{y:,.2f}}<extra></extra>",
        )
    )
    figure.add_hline(y=0, line_width=1.2, line_color="rgba(245,248,255,0.75)")
    figure.add_vline(x=stock_price, line_width=1.2, line_color="rgba(255,255,255,0.5)", line_dash="dot")
    figure.add_vline(x=structure.breakeven, line_width=1.4, line_color="rgba(74, 184, 255, 0.9)")
    x_span = float(x_prices[-1] - x_prices[0])
    close_labels = abs(structure.breakeven - stock_price) < (x_span * 0.045)
    figure.add_annotation(
        x=stock_price,
        y=0.97,
        yref="paper",
        text=f"{ticker_label} Price {stock_price:,.2f}",
        showarrow=False,
        xanchor="center",
        font={"color": "#dfeaff", "size": 12},
    )
    figure.add_annotation(
        x=structure.breakeven,
        y=0.885,
        yref="paper",
        text=f"Breakeven {structure.breakeven:,.2f}",
        showarrow=False,
        xanchor="center",
        xshift=(34 if structure.breakeven >= stock_price else -34) if close_labels else 0,
        font={"color": "#4ab8ff", "size": 12},
    )

    y_title = mode
    figure.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(9,17,30,0.78)",
        height=470,
        margin={"l": 10, "r": 10, "t": 12, "b": 10},
        legend={"orientation": "h", "x": 0.0, "y": 1.04, "font": {"color": "#dfeaff"}},
        xaxis={
            "title": {"text": f"{ticker_label} Price", "font": {"color": "#dfeaff"}},
            "showgrid": True,
            "gridcolor": "rgba(255,255,255,0.06)",
            "zeroline": False,
            "tickfont": {"color": "#dfeaff"},
        },
        yaxis={
            "title": {"text": y_title, "font": {"color": "#dfeaff"}},
            "showgrid": True,
            "gridcolor": "rgba(255,255,255,0.06)",
            "zeroline": False,
            "tickfont": {"color": "#dfeaff"},
        },
        yaxis2={
            "overlaying": "y",
            "side": "right",
            "showgrid": False,
            "showticklabels": False,
            "range": [0, 60],
        },
        hovermode="x unified",
        hoverlabel={"namelength": -1},
    )
    figure.update_xaxes(hoverformat="$,.2f")
    return figure


def metric_card(label: str, value: str, accent_class: str = "") -> str:
    return textwrap.dedent(f"""
    <div class='delta-metric-card {accent_class}'>
        <div class='delta-metric-label'>{label}</div>
        <div class='delta-metric-value'>{value}</div>
    </div>
    """).strip()


def readout_html(structure: Structure, ticker: str, stock_price: float, dte: int) -> str:
    rows = []
    for leg in structure.legs:
        side_word = "Buy" if leg.side == "long" else "Sell"
        strike_text = "Stock" if leg.asset_type == "stock" else f"{leg.strike:,.2f}"
        mid_text = f"{leg.entry_price:,.2f}" if leg.asset_type == "option" else f"{leg.entry_price:,.2f}"
        delta_text = "1.00" if leg.asset_type == "stock" else f"{leg.delta:.2f}"
        name = "Long Stock" if leg.asset_type == "stock" else f"{side_word} {leg.kind.title()}"
        rows.append(
            f"<tr><td>{name}</td><td>{strike_text}</td><td>{mid_text}</td><td>{delta_text}</td><td>{side_word} {leg.qty}</td></tr>"
        )

    while len(rows) < 5:
        rows.append("<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>")

    net_label = "Net Credit" if structure.net_credit > 0 else "Net Debit"
    net_value = structure.net_credit if structure.net_credit > 0 else structure.net_debit

    return f"""
    <div class='delta-side-card'>
        <div class='delta-side-title'>Current Position Snapshot</div>
        <div class='delta-side-pill'>{structure.strategy} • {structure.bias}</div>
        <table class='delta-position-table'>
            <thead>
                <tr><th>Leg</th><th>Strike</th><th>Mid</th><th>Delta</th><th>Position</th></tr>
            </thead>
            <tbody>
                {''.join(rows)}
            </tbody>
        </table>
        <div class='delta-readout-grid'>
            <div><span>Underlying</span><strong>{ticker.upper()} @ ${stock_price:,.2f}</strong></div>
            <div><span>EXP / DTE</span><strong>{dte} DTE</strong></div>
            <div><span>Breakeven</span><strong>${structure.breakeven:,.2f}</strong></div>
            <div><span>{net_label}</span><strong>${net_value:,.2f}</strong></div>
            <div><span>Max Profit</span><strong>{format_money(structure.max_profit)}</strong></div>
            <div><span>Max Loss</span><strong>{format_money(structure.max_loss)}</strong></div>
            <div><span>Chance of Profit</span><strong>{structure.chance_of_profit:.1f}%</strong></div>
            <div><span>Capital Required</span><strong>${structure.capital_required:,.2f}</strong></div>
        </div>
        <div class='delta-note-box'>
            <div class='delta-note-title'>Planner Note</div>
            <div class='delta-note-text'>{structure.note}</div>
        </div>
    </div>
    """


def strategy_explainer_html(structure: Structure) -> str:
    tag_chunks = []
    for chunk in structure.tags.split("•"):
        tag_chunks.append(f"<span class='delta-tag' style='border-color:{structure.accent}; color:{structure.accent};'>{chunk.strip()}</span>")
    return f"""
    <div class='delta-explainer'>
        <div>
            <div class='delta-section-kicker'>Strategy Guide</div>
            <div class='delta-explainer-title'>{structure.strategy}</div>
            <div class='delta-tag-row'>{''.join(tag_chunks)}</div>
            <div class='delta-explainer-copy'>{structure.summary}</div>
            <div class='delta-explainer-copy'>{structure.guide}</div>
        </div>
        <div class='delta-mini-box'>
            {mini_graph_svg(structure.strategy, structure.accent)}
        </div>
    </div>
    """




def width_label_for_strategy(strategy: str) -> str:
    if strategy in {"Bull Call Spread", "Bull Put Spread", "Bear Call Spread"}:
        return "Spread Width"
    return "Secondary Distance (not used for this setup)"


def uses_secondary_width(strategy: str) -> bool:
    return strategy in {"Bull Call Spread", "Bull Put Spread", "Bear Call Spread"}

